def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    MOD = 1_000_000_007

    children = [{}]
    terminal = [False]

    for word in banned:
        state = 0
        for char in word:
            if char not in children[state]:
                children[state][char] = len(children)
                children.append({})
                terminal.append(False)
            state = children[state][char]
        terminal[state] = True

    from collections import deque

    failure = [0] * len(children)
    queue = deque()

    for char in alphabet:
        if char in children[0]:
            queue.append(children[0][char])
        else:
            children[0][char] = 0

    while queue:
        state = queue.popleft()
        terminal[state] |= terminal[failure[state]]

        for char in alphabet:
            if char in children[state]:
                child = children[state][char]
                failure[child] = children[failure[state]][char]
                queue.append(child)
            else:
                children[state][char] = children[failure[state]][char]

    states = [state for state in range(len(children)) if not terminal[state]]
    index = {state: i for i, state in enumerate(states)}
    size = len(states)

    matrix = [[0] * size for _ in range(size)]
    for state in states:
        row = matrix[index[state]]
        for char in alphabet:
            target = children[state][char]
            if not terminal[target]:
                row[index[target]] += 1

    vector = [0] * size
    vector[index[0]] = 1

    while n:
        if n & 1:
            result = [0] * size
            for i, value in enumerate(vector):
                if value:
                    for j, coefficient in enumerate(matrix[i]):
                        if coefficient:
                            result[j] = (result[j] + value * coefficient) % MOD
            vector = result

        n >>= 1
        if n:
            squared = [[0] * size for _ in range(size)]
            for i in range(size):
                for k, value in enumerate(matrix[i]):
                    if value:
                        for j, coefficient in enumerate(matrix[k]):
                            if coefficient:
                                squared[i][j] = (
                                    squared[i][j] + value * coefficient
                                ) % MOD
            matrix = squared

    return sum(vector) % MOD
